//! Bounded offline NAD1/NAB1 inspection. No live selection issuer, actor profile,
//! native update/events/layer schedule, game wire or renderer Loaded grant.
use anyhow::{Result,ensure,Context};
use sha2::{Digest,Sha256};
use std::collections::{BTreeMap,BTreeSet};
const NAD_DOMAIN:&[u8]=b"LITO-NATIVE-APPEARANCE-DEPENDENCIES\0";
const NAB_DOMAIN:&[u8]=b"LITO-NATIVE-APPEARANCE-BINDING-EVIDENCE\0";
struct Reader<'a>{b:&'a[u8],at:usize}
impl<'a> Reader<'a>{fn take(&mut self,n:usize)->Result<&'a[u8]>{ensure!(n<=self.b.len().saturating_sub(self.at),"Truncated appearance evidence");let v=&self.b[self.at..self.at+n];self.at+=n;Ok(v)}fn u8(&mut self)->Result<u8>{Ok(self.take(1)?[0])}fn u16(&mut self)->Result<u16>{Ok(u16::from_be_bytes(self.take(2)?.try_into()?))}fn u32(&mut self)->Result<u32>{Ok(u32::from_be_bytes(self.take(4)?.try_into()?))}fn u64(&mut self)->Result<u64>{Ok(u64::from_be_bytes(self.take(8)?.try_into()?))}fn i64(&mut self)->Result<i64>{Ok(self.u64()? as i64)}fn i32(&mut self)->Result<i32>{Ok(self.u32()? as i32)}fn boolean(&mut self)->Result<bool>{let v=self.u8()?;ensure!(v<=1,"Nonboolean appearance flag");Ok(v==1)}fn count(&mut self,max:usize)->Result<usize>{let v=self.u16()? as usize;ensure!(v>0&&v<=max,"Appearance count bound");Ok(v)}}
fn envelope<'a>(b:&'a[u8],domain:&[u8],magic:&[u8],max:usize)->Result<Reader<'a>>{ensure!((40..=max).contains(&b.len()),"Appearance evidence byte bound");let end=b.len()-32;let mut h=Sha256::new();h.update(domain);h.update(&b[..end]);ensure!(h.finalize().as_slice()==&b[end..],"Appearance evidence digest");let mut r=Reader{b:&b[..end],at:0};ensure!(r.take(4)?==magic&&r.u16()?==1,"Appearance schema/magic");Ok(r)}
#[derive(Clone,Debug,PartialEq,Eq)]pub(crate) struct CatalogFrame{pub image:u32,pub subframe:u32,pub ticks:u16,pub events:Vec<u8>}
#[derive(Clone,Debug,PartialEq,Eq)]pub(crate) struct Action{pub id:u16,pub eight_way:bool,pub fps:u8,pub frames:Vec<CatalogFrame>}
#[derive(Clone,Debug,PartialEq,Eq)]pub(crate) struct Row{pub logical:u32,pub graphics:u32,pub actions:BTreeMap<u16,Action>}
#[derive(Clone,Debug,PartialEq,Eq)]pub(crate) struct Member{pub name:String,pub shard:u8,pub base:bool,pub offset:u64,pub bytes:u64,pub frames:u16,pub sha256:[u8;32]}
#[derive(Clone,Debug)]pub(crate) struct Dependencies{pub rows:BTreeMap<u32,Row>,pub members:BTreeMap<String,Member>}
pub(crate) fn nad(b:&[u8])->Result<Dependencies>{let mut r=envelope(b,NAD_DOMAIN,b"NAD1",128*1024)?;ensure!(r.count(2)?==2,"Exact base row matrix");let mut rows=BTreeMap::new();for _ in 0..2{let logical=r.u32()?;let graphics=r.u32()?;ensure!(matches!((logical,graphics),(0,3225)|(734,3476)),"Unqualified logical/image bank");let n=r.count(9)?;ensure!(n==9,"Exact action matrix");let mut actions=BTreeMap::new();for _ in 0..n{let id=r.u16()?;let eight_way=r.boolean()?;let fps=r.u8()?;ensure!(fps>0&&fps<=120,"Catalog FPS bound");let n=r.count(256)?;let mut frames=Vec::with_capacity(n);for _ in 0..n{let image=r.u32()?;let subframe=r.u32()?;let ticks=r.u16()?;ensure!(image<=65535&&subframe<255,"Catalog image/subframe bound");let length=r.u16()? as usize;ensure!(length<=256,"Event byte bound");frames.push(CatalogFrame{image,subframe,ticks,events:r.take(length)?.to_vec()});}ensure!(actions.insert(id,Action{id,eight_way,fps,frames}).is_none(),"Duplicate action");}let expected=if logical==0{vec![0,1,2,3,8,50,51,52,53]}else{vec![0,1,2,3,8,46,47,48,49]};ensure!(actions.keys().copied().collect::<Vec<_>>()==expected,"Unqualified action bank");ensure!(rows.insert(logical,Row{logical,graphics,actions}).is_none(),"Duplicate logical row");}
 let n=r.count(512)?;ensure!(n==144,"Exact base member matrix");let mut members=BTreeMap::new();for _ in 0..n{let length=r.u8()? as usize;ensure!((1..=40).contains(&length),"Member filename bound");let name=std::str::from_utf8(r.take(length)?)?.to_owned();ensure!(name.bytes().all(|x|x.is_ascii_digit()||x==b'-'||x==b'.'||x==b's'||x==b'p'||x==b'r')&&name.ends_with(".spr")&&!name.contains(".."),"Noncanonical member filename");let shard=r.u8()?;let base=r.boolean()?;let offset=r.u64()?;let bytes=r.u64()?;let frames=r.u16()?;let sha256=r.take(32)?.try_into()?;ensure!(shard<16&&shard==name.bytes().map(u32::from).sum::<u32>() as u8%16&&bytes>0&&bytes<=1024*1024&&offset.checked_add(bytes).is_some()&&(1..=255).contains(&frames),"Member route bounds");ensure!(members.insert(name.clone(),Member{name,shard,base,offset,bytes,frames,sha256}).is_none(),"Duplicate member");}ensure!(r.at==r.b.len(),"Trailing NAD1 payload");let mut used=BTreeSet::new();for row in rows.values(){for action in row.actions.values(){for f in &action.frames{for heading in 0..if action.eight_way{8}else{1}{let name=format!("{}-{}.spr",row.graphics,f.image+heading);let m=members.get(&name).context("Missing frame member")?;ensure!(f.subframe<m.frames as u32,"SPR subframe outside selected member");used.insert(name);}}}}ensure!(used.len()==144,"Incomplete member coverage");Ok(Dependencies{rows,members})}
#[derive(Clone,Debug,PartialEq,Eq)]pub(crate) struct Binding{pub source:u32,pub object:i64,pub epoch:u64,pub channel:u32,pub revision:i64,pub observed:i64,pub cutoff:i64,pub owner:[u8;32],pub catalog:[u8;32],pub character_type:u16,pub sex:u8,pub class:i32,pub weapon:i64,pub retained_type:u16,pub effective_equipped:bool}
pub(crate) fn nab(b:&[u8])->Result<Vec<Binding>>{let mut r=envelope(b,NAB_DOMAIN,b"NAB1",4096)?;ensure!(r.count(4)?==4,"Exact offline binding cases");let mut rows=Vec::new();let mut keys=BTreeSet::new();for _ in 0..4{let v=Binding{source:r.u32()?,object:r.i64()?,epoch:r.u64()?,channel:r.u32()?,revision:r.i64()?,observed:r.i64()?,cutoff:r.i64()?,owner:r.take(32)?.try_into()?,catalog:r.take(32)?.try_into()?,character_type:r.u16()?,sex:r.u8()?,class:r.i32()?,weapon:r.i64()?,retained_type:r.u16()?,effective_equipped:r.boolean()?};ensure!(matches!(v.source,7|42)&&v.object>0&&v.epoch!=0&&v.channel<=3&&v.revision>=0&&v.observed>=0&&(v.cutoff==-1||v.cutoff>v.observed)&&v.owner!=[0;32]&&v.catalog!=[0;32],"Offline binding scope/time");ensure!(matches!((v.character_type,v.sex,v.class),(0,0,0)|(3,0,734)),"Explicit Class matrix");ensure!(if v.effective_equipped{v.weapon>0&&matches!((v.character_type,v.retained_type),(0,3)|(3,2))}else{v.weapon==0&&v.retained_type==0},"Effective weapon selection, not persisted equipped flag");ensure!(keys.insert((v.source,v.object,v.epoch,v.channel,v.revision)),"Duplicate binding");rows.push(v);}ensure!(r.at==r.b.len(),"Trailing NAB1 payload");Ok(rows)}
#[derive(Clone,Copy,Debug)]pub(crate) enum Kind{Walk,Attack,Damage,Idle,Death}
#[derive(Debug)]pub(crate) struct InspectionPlan<'a>{pub logical:u32,pub graphics:u32,pub action:u16,pub heading:u8,pub fps:u8,pub frames:Vec<(&'a CatalogFrame,&'a Member)>,pub renderer_ready:bool,pub runtime_qualified:bool,pub game_wire_profile:u32}
pub(crate) fn plan<'a>(enabled:bool,d:&'a Dependencies,input:&Binding,expected:&Binding,now:i64,kind:Kind,heading:u8,budget:usize)->Result<InspectionPlan<'a>>{ensure!(enabled,"Appearance inspector default off");ensure!(matches!((input.character_type,input.sex,input.class),(0,0,0)|(3,0,734)),"Explicit Class matrix");ensure!(if input.effective_equipped{input.weapon>0&&matches!((input.character_type,input.retained_type),(0,3)|(3,2))}else{input.weapon==0&&input.retained_type==0},"Effective weapon stance");ensure!(input==expected&&now>=input.observed&&(input.cutoff<0||now<input.cutoff),"Offline expected binding/time mismatch; not live admission");ensure!(heading<8&&budget>0&&budget<=256,"Heading/inspection budget");let logical=input.class as u32;let row=d.rows.get(&logical).context("Missing explicit Class base row")?;let base=if !input.effective_equipped{0}else if input.retained_type==3{50}else if input.retained_type==2{46}else{anyhow::bail!("Unqualified weapon action family")};let id=match kind{Kind::Walk=>base,Kind::Attack=>base+1,Kind::Damage=>base+2,Kind::Idle=>base+3,Kind::Death=>8};let action=row.actions.get(&id).context("Action absent")?;ensure!(action.frames.len()<=budget&&(action.eight_way||heading==0),"Action/heading budget");let frames=action.frames.iter().map(|f|{let name=format!("{}-{}.spr",row.graphics,f.image+heading as u32);Ok((f,d.members.get(&name).context("Missing direct image bank member")?))}).collect::<Result<Vec<_>>>()?;Ok(InspectionPlan{logical,graphics:row.graphics,action:id,heading,fps:action.fps,frames,renderer_ready:false,runtime_qualified:false,game_wire_profile:0})}
